231   ////////////////////////
232   // Pipeline stage IC0 //
233   ////////////////////////
234 
235   // Cache lookup
236   assign lookup_throttle  = (fb_fill_level > FB_THRESHOLD[$clog2(NUM_FB)-1:0]);
237 
238   assign lookup_req_ic0   = req_i & ~&fill_busy_q & (branch_or_mispredict | ~lookup_throttle) &
239                             ~ecc_write_req;
240   assign lookup_addr_ic0  = branch_i            ? addr_i :
241                             branch_mispredict_i ? mispredict_addr_i :
242                                                   prefetch_addr_q;
243   assign lookup_index_ic0 = lookup_addr_ic0[IC_INDEX_HI:IC_LINE_W];
244 
245   // Cache write
246   assign fill_req_ic0   = (|fill_ram_req);
247   assign fill_index_ic0 = fill_ram_req_addr[IC_INDEX_HI:IC_LINE_W];
248   assign fill_tag_ic0   = {(~inval_prog_q & ~ecc_write_req),
249                            fill_ram_req_addr[ADDR_W-1:IC_INDEX_HI+1]};
250   assign fill_wdata_ic0 = fill_ram_req_data;
251 
252   // Arbitrated signals - lookups have highest priority
253   assign lookup_grant_ic0  = lookup_req_ic0;
254   assign fill_grant_ic0    = fill_req_ic0 & ~lookup_req_ic0 & ~inval_prog_q &
255                              ~ecc_write_req;
256   // Qualified lookup grant to mask ram signals in IC1 if access was not made
257   assign lookup_actual_ic0 = lookup_grant_ic0 & icache_enable_i & ~inval_prog_q &
258                              ~icache_inval_i & ~inval_lock & ~start_inval;
259 
260   // Tagram
261   assign tag_req_ic0   = lookup_req_ic0 | fill_req_ic0 | inval_prog_q | ecc_write_req;
262   assign tag_index_ic0 = inval_prog_q   ? inval_index_q :
263                          ecc_write_req  ? ecc_write_index :
264                          fill_grant_ic0 ? fill_index_ic0 :
265                                           lookup_index_ic0;
266   assign tag_banks_ic0 = ecc_write_req  ? ecc_write_ways :
267                          fill_grant_ic0 ? fill_ram_req_way :
268                                           {IC_NUM_WAYS{1'b1}};
269   assign tag_write_ic0 = fill_grant_ic0 | inval_prog_q | ecc_write_req;
270 
271   // Dataram
272   assign data_req_ic0   = lookup_req_ic0 | fill_req_ic0;
273   assign data_index_ic0 = tag_index_ic0;
274   assign data_banks_ic0 = tag_banks_ic0;
275   assign data_write_ic0 = tag_write_ic0;
276 
277   // Append ECC checkbits to write data if required
278   if (ICacheECC) begin : gen_ecc_wdata
279 
280     // Tagram ECC
281     // Reuse the same ecc encoding module for larger cache sizes by padding with zeros
282     logic [21:0]             tag_ecc_input_padded;
283     logic [27:0]             tag_ecc_output_padded;
284     logic [22-IC_TAG_SIZE:0] unused_tag_ecc_output;
285 
286     assign tag_ecc_input_padded  = {{22-IC_TAG_SIZE{1'b0}},fill_tag_ic0};
287     assign unused_tag_ecc_output = tag_ecc_output_padded[21:IC_TAG_SIZE-1];
288 
289     prim_secded_inv_28_22_enc tag_ecc_enc (
290       .data_i (tag_ecc_input_padded),
291       .data_o (tag_ecc_output_padded)
292     );
293 
294     assign tag_wdata_ic0 = {tag_ecc_output_padded[27:22],tag_ecc_output_padded[IC_TAG_SIZE-1:0]};
295 
296     // Dataram ECC
297     for (genvar bank = 0; bank < IC_LINE_BEATS; bank++) begin : gen_ecc_banks
298       prim_secded_inv_39_32_enc data_ecc_enc (
299         .data_i (fill_wdata_ic0[bank*BUS_SIZE+:BUS_SIZE]),
300         .data_o (data_wdata_ic0[bank*BusSizeECC+:BusSizeECC])
301       );
302     end
303 
304   end else begin : gen_noecc_wdata
305     assign tag_wdata_ic0  = fill_tag_ic0;
306     assign data_wdata_ic0 = fill_wdata_ic0;
307   end
308 
309   ////////////////
310   // IC0 -> IC1 //
311   ////////////////
312 
313   // Tag RAMs outputs
314   assign ic_tag_req_o    = {IC_NUM_WAYS{tag_req_ic0}} & tag_banks_ic0;
315   assign ic_tag_write_o  = tag_write_ic0;
316   assign ic_tag_addr_o   = tag_index_ic0;
317   assign ic_tag_wdata_o  = tag_wdata_ic0;
318 
319   // Tag RAMs inputs
320   assign tag_rdata_ic1   = ic_tag_rdata_i;
321 
322   // Data RAMs outputs
323   assign ic_data_req_o   = {IC_NUM_WAYS{data_req_ic0}} & data_banks_ic0;
324   assign ic_data_write_o = data_write_ic0;
325   assign ic_data_addr_o  = data_index_ic0;
326   assign ic_data_wdata_o = data_wdata_ic0;
327 
328   // Data RAMs inputs
329   assign data_rdata_ic1  = ic_data_rdata_i;
330 
331   always_ff @(posedge clk_i or negedge rst_ni) begin
332     if (!rst_ni) begin
333       lookup_valid_ic1 <= 1'b0;
334     end else begin
335       lookup_valid_ic1 <= lookup_actual_ic0;
336     end
337   end
338 
339   if (ResetAll) begin : g_lookup_addr_ra
340     always_ff @(posedge clk_i or negedge rst_ni) begin
341       if (!rst_ni) begin
342         lookup_addr_ic1 <= '0;
343         fill_in_ic1     <= '0;
344       end else if (lookup_grant_ic0) begin
345         lookup_addr_ic1 <= lookup_addr_ic0[ADDR_W-1:IC_INDEX_HI+1];
346         fill_in_ic1     <= fill_alloc_sel;
347       end
348     end
349   end else begin : g_lookup_addr_nr
350     always_ff @(posedge clk_i) begin
351       if (lookup_grant_ic0) begin
352         lookup_addr_ic1 <= lookup_addr_ic0[ADDR_W-1:IC_INDEX_HI+1];
353         fill_in_ic1     <= fill_alloc_sel;
354       end
355     end
356   end
357 
358   ////////////////////////
359   // Pipeline stage IC1 //
360   ////////////////////////
361 
362   // Tag matching
363   for (genvar way = 0; way < IC_NUM_WAYS; way++) begin : gen_tag_match
364     assign tag_match_ic1[way]   = (tag_rdata_ic1[way][IC_TAG_SIZE-1:0] ==
365                                    {1'b1,lookup_addr_ic1[ADDR_W-1:IC_INDEX_HI+1]});
366     assign tag_invalid_ic1[way] = ~tag_rdata_ic1[way][IC_TAG_SIZE-1];
367   end
368 
369   assign tag_hit_ic1 = |tag_match_ic1;
370 
371   // Hit data mux
372   always_comb begin
373     hit_data_ecc_ic1 = 'b0;
374     for (int way = 0; way < IC_NUM_WAYS; way++) begin
375       if (tag_match_ic1[way]) begin
376         hit_data_ecc_ic1 |= data_rdata_ic1[way];
377       end
378     end
379   end
380 
381   // Way selection for allocations to the cache (onehot signals)
382   // 1 first invalid way
383   // 2 global round-robin (pseudorandom) way
384   assign lowest_invalid_way_ic1[0] = tag_invalid_ic1[0];
385   assign round_robin_way_ic1[0]    = round_robin_way_q[IC_NUM_WAYS-1];
386   for (genvar way = 1; way < IC_NUM_WAYS; way++) begin : gen_lowest_way
387     assign lowest_invalid_way_ic1[way] = tag_invalid_ic1[way] & ~|tag_invalid_ic1[way-1:0];
388     assign round_robin_way_ic1[way]    = round_robin_way_q[way-1];
389   end
390 
391   always_ff @(posedge clk_i or negedge rst_ni) begin
392     if (!rst_ni) begin
393       round_robin_way_q <= {{IC_NUM_WAYS-1{1'b0}}, 1'b1};
394     end else if (lookup_valid_ic1) begin
395       round_robin_way_q <= round_robin_way_ic1;
396     end
397   end
398 
399   assign sel_way_ic1 = |tag_invalid_ic1 ? lowest_invalid_way_ic1 :
400                                           round_robin_way_q;
401 
402   // ECC checking logic
